                  .map((t) => t.displayName);
                const ignoring = tools
                  .filter((t) => !toolAcceptsInlinePrompt(t.id))
                  .map((t) => t.displayName);
                return (
                  <>
                    <span style={{ color: 'var(--healthy)' }}>Sent to:</span>{' '}
                    {accepting.join(', ') || 'none'}
                    {ignoring.length > 0 && (
                      <>
                        {' · '}
                        <span className="text-muted-foreground/60">Ignored by:</span>{' '}
                        {ignoring.join(', ')}
                      </>
                    )}
                  </>
                );
              })

